{
  "name": "bt_rx_handle_desc",
  "confidence": "medium",
  "docstring": "Handles a Bluetooth RX descriptor by selecting its PHY context, optionally scheduling or marking a receive-window move after a flush, then inserting the descriptor into the HCI RX ring and draining pending ring entries.",
  "subsystem": "bt",
  "var_renames": {
    "a1": "rx_desc",
    "v4": "ctx_offset",
    "v5": "sub_ctx",
    "v8": "hci_queue_id",
    "v11": "hci_queue_ctx",
    "v12": "desc_flag_shifted",
    "v13": "rx_ring",
    "v14": "window_target",
    "v15": "timer_now",
    "v16": "timer_now",
    "v17": "ring_entry",
    "v18": "ring_index_fn",
    "v19": "entry_index",
    "v20": "timer_now",
    "i": "processed_entries"
  },
  "struct_hints": [
    {
      "offset": 29,
      "meaning": "rx_desc byte: PHY/context index used to select a 696-byte Bluetooth context"
    },
    {
      "offset": 27,
      "meaning": "rx_desc byte: sub-index selecting a 12-byte slot inside the Bluetooth context"
    },
    {
      "offset": 30,
      "meaning": "rx_desc uint16: flags; bit 1 must be set for RX processing"
    },
    {
      "offset": 32,
      "meaning": "rx_desc uint16: sequence/timestamp offset used to compute an RX ring entry index"
    },
    {
      "offset": 36,
      "meaning": "rx_desc uint32: length/flag word; sign after shifting selects the flush/window path"
    },
    {
      "offset": 64,
      "meaning": "rx_desc uint16: receive-window deadline tick value"
    },
    {
      "offset": 76,
      "meaning": "rx_desc pointer: event/queue state object whose +4 flag may be set"
    },
    {
      "offset": 4,
      "meaning": "Bluetooth context uint32: state flags; bit 1 indicates usable context"
    },
    {
      "offset": 453,
      "meaning": "Bluetooth context byte: HCI queue/event identifier"
    },
    {
      "offset": 455,
      "meaning": "Bluetooth context byte: pending count decremented when a descriptor arrives"
    },
    {
      "offset": 4,
      "meaning": "HCI queue context pending count"
    },
    {
      "offset": 28,
      "meaning": "HCI queue context pointer to RX ring"
    },
    {
      "offset": 4,
      "meaning": "RX ring head index, masked to 12 bits"
    },
    {
      "offset": 262,
      "meaning": "RX ring current entry/tail index"
    },
    {
      "offset": 6,
      "meaning": "RX ring entry state byte; value 2 marks entry pending for drain"
    }
  ]
}
